import {PHASES,buildReview} from './review.mjs';
import {MAX_BYTES,parseTranscript,selectCues} from './model.mjs';
export function mount({container,search='',signal,theme}={}){
 const root=container.attachShadow({mode:'open'});let data=null,disposed=false,generation=0,page=0,downloadUrl=null;
 root.innerHTML='<section><p>ATHENA · EVIDENCE FIRST</p><h2>Video study desk</h2><p>Study the problem, failed attempts, solution and verification. Imported captions are evidence, not proof of mastery.</p><label>Open normalized transcript JSON<input id="import" type="file" accept=".json,application/json"></label><button id="clear">Clear transcript</button><p id="notice" role="status">Generate JSON with scripts/video_learning.py from captions you are authorized to use. Nothing is uploaded or saved in browser storage. Leaving clears this session.</p><p id="identity"></p><p id="count" aria-live="polite"></p><div id="cues"></div><button id="previous">Previous 50</button><button id="next">Next 50</button><form id="review"><h3>Evidence review draft</h3><p>Write your own analysis. Label fictionalized stories as illustrative. Citation links establish traceability, not correctness. Export before leaving; drafts are session-only and reset when a new transcript is imported.</p><fieldset id="review-fields" disabled></fieldset></form><footer>Coverage: imported cues only. Full video, visual evidence and channel coverage are not established. Automatic captions may be inaccurate or repeat. Use timestamp links to verify against the original. Curriculum admission remains separate and review-gated.</footer></section>';
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./style.css',import.meta.url);root.prepend(css);
 const $=s=>root.querySelector(s),node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
 const fields=$('#review-fields');
 const label=(title,control)=>{const l=node('label',title);l.append(control);fields.append(l);return control;};
 function select(name,options){const e=document.createElement('select');e.id=name;for(const option of options){const o=node('option',option);o.value=option;e.append(o);}return e;}
 function area(name,max=4000){const e=document.createElement('textarea');e.id=name;e.maxLength=max;return e;}
 label('Source kind',select('source-kind',['unverified','illustrative-story','documented-incident']));
 for(const phase of PHASES){fields.append(node('h4',phase));label('Classification',select(phase+'-status',['unknown','observed','inferred']));label('Analysis / explicitly missing evidence',area(phase+'-statement'));const refs=document.createElement('input');refs.id=phase+'-refs';refs.maxLength=2000;label('Cue IDs, comma separated (example: cue-1, cue-2)',refs);}
 label('Learning objectives, one per line',area('objectives',20000));for(const key of ['task','success_criteria','safety'])label('Exercise '+key.replaceAll('_',' '),area(key,10000));const exportButton=node('button','Export review draft');exportButton.type='submit';fields.append(exportButton);
 function resetReview(){for(const e of fields.querySelectorAll('textarea,input'))e.value='';for(const e of fields.querySelectorAll('select')){for(const option of e.querySelectorAll('option'))option.removeAttribute('selected');e.querySelector('option').selected=true;}fields.disabled=!data;if(downloadUrl){URL.revokeObjectURL(downloadUrl);downloadUrl=null;}}
 $('#review').onsubmit=e=>{e.preventDefault();if(disposed||!data)return;try{const input={source_kind:$('#source-kind').value,objectives:$('#objectives').value,exercise:{}};for(const phase of PHASES)input[phase]={status:$('#'+phase+'-status').value,statement:$('#'+phase+'-statement').value,cue_ids:$('#'+phase+'-refs').value.split(',').map(s=>s.trim()).filter(Boolean)};for(const key of ['task','success_criteria','safety'])input.exercise[key]=$('#'+key).value;const review=buildReview(data,input);if(downloadUrl)URL.revokeObjectURL(downloadUrl);downloadUrl=URL.createObjectURL(new Blob([JSON.stringify(review,null,2)],{type:'application/json'}));const a=node('a','');a.href=downloadUrl;a.download='athena-video-review-'+data.video_id+'.json';a.click();$('#notice').textContent='Review download requested. Validate it with video_learning.py --review; no curriculum admission or mastery was granted.';}catch(error){$('#notice').textContent=error.message;}};
 function render(){if(disposed)return;$('#cues').replaceChildren();$('#identity').textContent=data?`${data.video_id} · ${data.language} · ${data.origin} · ${data.automatic?'Automatic captions':'Caption origin supplied by importer'} · SHA256 ${data.sha256}`:'';const result=data?selectCues(data,search,page):{total:0,pages:1,page:0,cues:[]};page=result.page;$('#count').textContent=`${result.total} matching cues · page ${page+1}/${result.pages}`;$('#previous').disabled=page===0;$('#next').disabled=page+1>=result.pages;
 for(const c of result.cues){const card=node('article',''),link=node('a',`${c.id} · ${(c.start_ms/1000).toFixed(1)}–${(c.end_ms/1000).toFixed(1)} seconds ↗`);link.href=c.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link,node('p',c.text));$('#cues').append(card);}}
 $('#import').onchange=async e=>{const file=e.target.files?.[0],token=++generation;e.target.value='';if(!file||disposed)return;$('#notice').textContent='Reading selected transcript…';try{if(file.size>MAX_BYTES)throw Error('Transcript exceeds 16 MiB.');const bytes=await file.arrayBuffer();if(disposed||token!==generation)return;const next=parseTranscript(new Uint8Array(bytes));if(disposed||token!==generation)return;data=next;page=0;resetReview();render();$('#notice').textContent='Imported for this session only. Source claims and completeness still require review.';}catch(error){if(!disposed&&token===generation)$('#notice').textContent='Import refused; previous transcript retained. '+error.message;}};
 $('#clear').onclick=()=>{generation++;data=null;page=0;resetReview();render();$('#notice').textContent='Transcript cleared.';};$('#previous').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};
 function unmount(){if(disposed)return;disposed=true;generation++;data=null;if(downloadUrl)URL.revokeObjectURL(downloadUrl);downloadUrl=null;root.replaceChildren();signal?.removeEventListener('abort',unmount);}function setTheme(t){container.dataset.theme=t==='light'?'light':'dark';}setTheme(theme);resetReview();render();signal?.addEventListener('abort',unmount,{once:true});if(signal?.aborted)unmount();return {unmount,setTheme,setSearch(q){search=String(q);page=0;render();}};
}
